if(tab==='orders'){const p=section('訂單與付款管理');p.append(node('p','正式付款與測試紀錄分開標示。未確認收款不可完成訂單；待付款訂單保留名額／庫存。取消不等於退款，已收款取消前須另行完成退款核對。完成／取消後不可重新開啟。'));for(const o of data.orders){const r=row(),b=node('div',undefined,'grow');b.append(node('b',o.member_name+' · '+(o.kind==='inquiry'?'詢價單':'預約單')),node('small',o.id+' · '+new Date(o.created_at*1000).toLocaleString('zh-TW')),node('p',o.items.map(i=>i.name+' × '+i.quantity).join('、')),node('p','參考合計 NT$'+o.total+' · 備註：'+(o.note||'無')));const s=select(Object.entries(statusNames));s.value=o.status;s.setAttribute('aria-label','訂單狀態');if(['completed','cancelled'].includes(o.status))s.disabled=true;if(o.payment_environment)b.append(node('p',(o.payment_environment==='stage'?'測試交易 · ':'正式收款 · ')+WildRidePayment.label(o.payment_status)));r.append(b,s,action('更新狀態',()=>mutate('order',{id:o.id,status:s.value})));p.append(r)}if(!data.orders.length)p.append(node('p','尚無訂單。'));host.append(p)}
