passwordDialog.addEventListener('close',()=>{passwordForm.reset();passwordMember=null;passwordFeedback.textContent=''});passwordDialog.addEventListener('cancel',e=>{if(passwordBusy)e.preventDefault()});
passwordForm.onsubmit=async e=>{e.preventDefault();if(passwordBusy||!passwordMember)return;if(newPassword.value!==confirmPassword.value){passwordFeedback.textContent='兩次新密碼輸入不一致。';return}passwordBusy=true;passwordSave.disabled=passwordCancel.disabled=true;passwordFeedback.textContent='正在重設密碼…';try{const result=await api.request('admin/member-password',{userId:passwordMember.id,newPassword:newPassword.value,confirmPassword:confirmPassword.value});passwordDialog.close();if(result.requiresLogin){await start();say('密碼已重設，請使用新密碼重新登入。')}else{await refresh();say(api.mode==='supabase'?'會員密碼已重設；既有登入憑證依 Supabase 工作階段與 JWT 有效期失效。':'會員密碼已重設，原有登入狀態已全部登出。')}}catch(error){passwordFeedback.textContent=error.message}finally{passwordBusy=false;passwordSave.disabled=passwordCancel.disabled=false}};

